// Flatten the three discovery-source shapes into individual OBSERVATION records.
// An observation is a raw, source-attributed sighting — it is NOT yet a resolved asset.
const crypto = require('crypto');
const cfg = $('Set Configuration Parameters').first().json;
const scanId = cfg.scanId;
const items = $input.all();

function obsFingerprint(rec) {
  const raw = [rec.source, rec.assetType, rec.identifier, rec.port || '', rec.service || ''].join('|').toLowerCase();
  return crypto.createHash('sha256').update(raw).digest('hex').slice(0, 16);
}

let observations = [];

for (const item of items) {
  const d = item.json;

  if (Array.isArray(d.subdomains)) {
    for (const s of d.subdomains) {
      const hostname = typeof s === 'string' ? s : (s.hostname || s.domain);
      observations.push({
        source: 'subdomain-enum',
        assetType: 'domain',
        identifier: hostname,
        hostname: hostname || null,
        ipAddress: (s && s.ip) || null,
        port: null,
        protocol: null,
        service: null,
        cloudProvider: null,
        region: null,
        arn: null
      });
    }
  }

  if (Array.isArray(d.services)) {
    for (const svc of d.services) {
      const host = svc.ip || svc.host;
      observations.push({
        source: 'exposed-service-scan',
        assetType: 'service',
        identifier: host + ':' + svc.port,
        hostname: svc.host || null,
        ipAddress: host || null,
        port: svc.port || null,
        protocol: svc.protocol || null,
        service: svc.service || svc.banner || null,
        cloudProvider: null,
        region: null,
        arn: null
      });
    }
  }

  if (Array.isArray(d.resources)) {
    for (const res of d.resources) {
      observations.push({
        source: 'cloud-inventory',
        assetType: 'cloud-resource',
        identifier: res.resourceId || res.arn || res.name,
        hostname: res.publicDns || null,
        ipAddress: res.publicIp || null,
        port: null,
        protocol: null,
        service: res.resourceType || null,
        cloudProvider: res.provider || null,
        region: res.region || null,
        arn: res.arn || null
      });
    }
  }
}

observations = observations
  .filter(o => !!o.identifier)
  .map(o => ({
    ...o,
    scanId,
    observedAt: new Date().toISOString(),
    observationFingerprint: obsFingerprint(o)
  }));

return observations.map(o => ({ json: o }));

// Deterministic identity resolution: collapse observations from multiple sources onto one asset_id.
// Match priority: ARN exact -> IP+port exact -> hostname exact -> IP-only fallback.
// If nothing matches, mint a new asset_id (new asset).
const crypto = require('crypto');

const allInput = $input.all();
const observations = [];
const identitiesSeen = new Map();

for (const item of allInput) {
  const d = item.json;
  if (d.observationFingerprint) {
    observations.push(d);
  }
  if (d.assetId) {
    identitiesSeen.set(d.assetId, d);
  }
}

const uniqueObs = [];
const seenFp = new Set();
for (const o of observations) {
  if (!seenFp.has(o.observationFingerprint)) { seenFp.add(o.observationFingerprint); uniqueObs.push(o); }
}

const identities = Array.from(identitiesSeen.values());

function newAssetId() {
  return 'asset_' + crypto.randomBytes(8).toString('hex');
}

function findMatch(obs) {
  for (const id of identities) {
    if (obs.arn && id.arn && obs.arn === id.arn) return id.assetId;
  }
  for (const id of identities) {
    if (obs.ipAddress && obs.port && id.ipAddress === obs.ipAddress && String(id.port) === String(obs.port)) return id.assetId;
  }
  for (const id of identities) {
    if (obs.hostname && id.hostname && obs.hostname.toLowerCase() === id.hostname.toLowerCase()) return id.assetId;
  }
  for (const id of identities) {
    if (obs.ipAddress && !obs.port && id.ipAddress === obs.ipAddress && id.assetType === obs.assetType) return id.assetId;
  }
  return null;
}

const mintedThisScan = [];

const resolved = uniqueObs.map(obs => {
  let assetId = findMatch(obs);
  if (!assetId) {
    const withinScan = mintedThisScan.find(m =>
      (obs.arn && m.arn === obs.arn) ||
      (obs.ipAddress && obs.port && m.ipAddress === obs.ipAddress && String(m.port) === String(obs.port)) ||
      (obs.hostname && m.hostname && obs.hostname.toLowerCase() === m.hostname.toLowerCase())
    );
    if (withinScan) {
      assetId = withinScan.assetId;
    } else {
      assetId = newAssetId();
      mintedThisScan.push({ assetId, arn: obs.arn, ipAddress: obs.ipAddress, port: obs.port, hostname: obs.hostname });
    }
  }
  return { ...obs, assetId, isNewAssetId: !identities.find(id => id.assetId === assetId) };
});

return resolved.map(r => ({ json: r }));

// Aggregate all resolved observations for the same asset_id (possibly from different sources)
// into ONE merged current-state record per asset.
const byAsset = new Map();

for (const item of $input.all()) {
  const o = item.json;
  if (!byAsset.has(o.assetId)) {
    byAsset.set(o.assetId, {
      assetId: o.assetId,
      assetType: o.assetType,
      identifier: o.identifier,
      hostname: o.hostname,
      ipAddress: o.ipAddress,
      ports: new Set(),
      services: new Set(),
      cloudProvider: o.cloudProvider,
      region: o.region,
      arn: o.arn,
      sources: new Set(),
      isNewAssetId: o.isNewAssetId,
      lastSeenAt: o.observedAt
    });
  }
  const a = byAsset.get(o.assetId);
  if (o.port) a.ports.add(String(o.port));
  if (o.service) a.services.add(o.service);
  a.sources.add(o.source);
  if (!a.hostname && o.hostname) a.hostname = o.hostname;
  if (!a.ipAddress && o.ipAddress) a.ipAddress = o.ipAddress;
  if (!a.cloudProvider && o.cloudProvider) a.cloudProvider = o.cloudProvider;
  if (!a.region && o.region) a.region = o.region;
  if (!a.arn && o.arn) a.arn = o.arn;
}

const current = Array.from(byAsset.values()).map(a => ({
  ...a,
  ports: Array.from(a.ports).sort(),
  services: Array.from(a.services).sort(),
  sources: Array.from(a.sources).sort()
}));

return current.map(c => ({ json: c }));

// Compare current merged state vs previous persisted state per asset and emit TYPED events.
// Zero, one, or several events can come out of a single asset comparison.
const cfg = $('Set Configuration Parameters').first().json;
const scanId = cfg.scanId;
const items = $input.all();

// The merge node (keepEverything, matched on assetId) can emit: paired rows (both sides present),
// current-only rows (new assets), or previous-only rows (decommissioned assets). Normalize defensively.
const records = new Map();
for (const item of items) {
  const d = item.json;
  const id = d.assetId;
  if (!id) continue;
  if (!records.has(id)) records.set(id, { current: null, previous: null });
  const rec = records.get(id);
  if (Object.prototype.hasOwnProperty.call(d, 'isNewAssetId')) {
    rec.current = d;
  } else if (Object.prototype.hasOwnProperty.call(d, 'lastSeverity') || Object.prototype.hasOwnProperty.call(d, 'lastSeenAt')) {
    rec.previous = d;
  } else {
    rec.current = rec.current || d;
  }
}

const events = [];

function arr(x) { return Array.isArray(x) ? x : (x ? [x] : []); }

for (const [assetId, rec] of records.entries()) {
  const curr = rec.current;
  const prev = rec.previous;
  if (!curr) continue;

  const base = {
    scanId,
    assetId,
    assetType: curr.assetType,
    identifier: curr.identifier,
    hostname: curr.hostname,
    ipAddress: curr.ipAddress,
    cloudProvider: curr.cloudProvider,
    region: curr.region,
    sources: curr.sources,
    detectedAt: new Date().toISOString()
  };

  if (!prev) {
    events.push({ ...base, eventType: 'asset.new', details: { ports: curr.ports, services: curr.services } });
    if (curr.assetType === 'cloud-resource') {
      events.push({ ...base, eventType: 'cloud_resource.added', details: { cloudProvider: curr.cloudProvider, region: curr.region } });
    }
    for (const p of arr(curr.ports)) {
      events.push({ ...base, eventType: 'service.added', details: { port: p } });
    }
    continue;
  }

  const prevPorts = new Set(arr(prev.ports));
  const currPorts = new Set(arr(curr.ports));
  for (const p of currPorts) {
    if (!prevPorts.has(p)) events.push({ ...base, eventType: 'service.added', details: { port: p } });
  }
  for (const p of prevPorts) {
    if (!currPorts.has(p)) events.push({ ...base, eventType: 'service.removed', details: { port: p } });
  }

  const prevServices = new Set(arr(prev.services));
  const currServices = new Set(arr(curr.services));
  for (const s of currServices) {
    if (!prevServices.has(s)) events.push({ ...base, eventType: 'attribute.changed', details: { field: 'service', newValue: s } });
  }

  if (prev.cloudProvider !== curr.cloudProvider || prev.region !== curr.region) {
    if (curr.cloudProvider || curr.region) {
      events.push({ ...base, eventType: 'attribute.changed', details: { field: 'cloud_location', from: { cloudProvider: prev.cloudProvider, region: prev.region }, to: { cloudProvider: curr.cloudProvider, region: curr.region } } });
    }
  }

  if (prev.ipAddress && curr.ipAddress && prev.ipAddress !== curr.ipAddress) {
    events.push({ ...base, eventType: 'attribute.changed', details: { field: 'ip_address', from: prev.ipAddress, to: curr.ipAddress } });
  }
}

const currentAssetIds = new Set(Array.from(records.values()).filter(r => r.current).map(r => r.current.assetId));
for (const [assetId, rec] of records.entries()) {
  if (rec.previous && !currentAssetIds.has(assetId)) {
    events.push({
      scanId, assetId,
      assetType: rec.previous.assetType,
      identifier: rec.previous.identifier,
      hostname: rec.previous.hostname,
      ipAddress: rec.previous.ipAddress,
      cloudProvider: rec.previous.cloudProvider,
      region: rec.previous.region,
      sources: rec.previous.sources,
      detectedAt: new Date().toISOString(),
      eventType: 'asset.decommissioned',
      details: {}
    });
  }
}

return events.map(e => ({ json: e }));

// Deterministic severity scoring per typed event, plus policy-relevant flags.
// This node decides WHAT the risk level is; it does not decide routing (policy engine does that later)
// and it does not generate the human-readable explanation (the AI agent does that later).
const cfg = $('Set Configuration Parameters').first().json;
const allowedProviders = String(cfg.allowedCloudProviders || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const allowedRegions = String(cfg.allowedCloudRegions || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);

const HIGH_RISK_PORTS = [21, 22, 23, 3389, 3306, 5432, 6379, 9200, 27017, 2375];
const SENSITIVE_KEYWORDS = ['admin', 'debug', 'staging', 'internal', 'jenkins', 'kibana', 'grafana', 'phpmyadmin'];

const items = $input.all();

const scored = items.map(item => {
  const d = item.json;
  let severity = 'low';
  const reasons = [];
  let isUnauthorizedCloudFootprint = false;
  let isRiskIncrease = false;

  const port = d.details && d.details.port;
  const isSensitiveName = d.identifier && SENSITIVE_KEYWORDS.some(k => String(d.identifier).toLowerCase().includes(k));

  switch (d.eventType) {
    case 'service.added':
      if (port && HIGH_RISK_PORTS.includes(Number(port))) {
        severity = 'critical'; reasons.push('Newly exposed high-risk port ' + port); isRiskIncrease = true;
      } else if (isSensitiveName) {
        severity = 'high'; reasons.push('Newly exposed service on a sensitive-named asset'); isRiskIncrease = true;
      } else {
        severity = 'high'; reasons.push('New externally exposed service detected'); isRiskIncrease = true;
      }
      break;
    case 'cloud_resource.added':
      severity = 'medium'; reasons.push('New cloud resource added to inventory');
      if ((d.cloudProvider && allowedProviders.length && !allowedProviders.includes(String(d.cloudProvider).toLowerCase())) ||
          (d.region && allowedRegions.length && !allowedRegions.includes(String(d.region).toLowerCase()))) {
        severity = 'critical'; reasons.push('Cloud resource is outside the approved provider/region allowlist'); isUnauthorizedCloudFootprint = true; isRiskIncrease = true;
      }
      break;
    case 'asset.new':
      severity = isSensitiveName ? 'high' : 'medium';
      reasons.push('New attack-surface asset discovered');
      break;
    case 'attribute.changed':
      severity = 'medium'; reasons.push('Existing asset attributes changed since last scan');
      break;
    case 'service.removed':
      severity = 'low'; reasons.push('A previously exposed service is no longer detected');
      break;
    case 'asset.decommissioned':
      severity = 'low'; reasons.push('Asset no longer detected — verify this was an intentional decommission');
      break;
    default:
      severity = 'low'; reasons.push('Unclassified change event');
  }

  return { json: { ...d, severity, reasons, isUnauthorizedCloudFootprint, isRiskIncrease } };
});

return scored;

// The AI Agent node only returns its own output, so re-attach the narrative to the original scored event.
const original = $('Score Event Risk').item.json;
const agentOutput = $input.item.json;
const aiRiskNote = String(agentOutput.output || agentOutput.text || agentOutput.response || '').trim();

return [{ json: { ...original, aiRiskNote } }];

// POLICY ENGINE: the single place that owns "where/how do we alert".
// Decoupled from risk scoring (already done) and from the AI narrative (already attached).
// Change this node to adjust org escalation policy without touching scoring or AI logic.
const items = $input.all();

function decide(e) {
  const routes = [];

  if (e.isUnauthorizedCloudFootprint) {
    routes.push('compliance_email');
  }

  if (e.severity === 'critical') {
    routes.push('slack');
  } else if (e.severity === 'high') {
    routes.push('slack');
  } else if (e.severity === 'medium') {
    routes.push('security_email');
  } else {
    routes.push('log_only');
  }

  return routes;
}

const out = items.map(item => {
  const e = item.json;
  const routes = decide(e);
  return { json: { ...e, routes } };
});

return out;
